css:
.button {
  position: relative;
  width: 3em;
  height: 3em;
  transform: rotateX(30deg);
  border-radius: 0.2em;
  border: 1px solid #3f3f3f;
  box-shadow: 0 0.3em 0 0.1em #3f3f3f;
  transition: all 150ms;
}

.button::after {
  position: absolute;
  content: "f5";
  inset-block: 0;
  inset-inline: 0;
  padding-block: 0.2em;
  padding-inline: 0.2em;
  text-align: end;
  color: #3f3f3f;
}

.button:active {
  transform: rotateX(30deg) translateY(0.3em);
  box-shadow: 0 0 0 0 #3f3f3f;
}
